package Lec1;

public class Maximum_3_Number {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a = 11;
		int b = 7;
		int c = 9;
		if(a>=b && a>=c) {
			System.out.println(a);
		}
		else if(b>=a && b>=c) {
			System.out.println(a);
		}
		else {
			System.out.println(c);
		}
	}

}
